contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint firstVal) public payable {
        bool firstReverted;
        c.SetMinSum(firstVal); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        uint minSumAfterFirst = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(!firstReverted && minSumAfterFirst == firstVal);
    }

    receive() external payable {}
}

