// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 firstVal) internal {
        bool firstReverted;
        try c.SetMinSum(firstVal) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }
        uint256 minSumAfterFirst;
        try c.MinSum() returns (uint256 __r) { minSumAfterFirst = __r; } catch { return; }
        assertTrue(!firstReverted && minSumAfterFirst == firstVal);
    }

    function testFuzz_run(uint256 firstVal) public {
        _run(firstVal);
    }

    receive() external payable {}
}
